"""Explains layers.15.mlp.down_proj component 964 (a weak, mostly context-driven unit).

What the component does, as far as simple concepts go: its activation is a signed value
with mean about -0.05 and spread about 0.5, and it is almost unrelated to which token is
present. Its largest positive values come on the word right after a relational word
("after", "before", "while", "between", "given", "date", ...) or after "the", and it is
pulled down after prepositions and conjunctions ("in", "on", "at", "for", "and"), on the
first few tokens of a document, and on whitespace and digit tokens.

This program predicts that as a sum of those few effects:
  - the first token of each document: 0 (the component is silent there);
  - otherwise a base level of -0.045;
  - -0.09 on the 2nd to 4th tokens of a document;
  - +0.27 if the previous word is a relational word, +0.15 if it is "the", "each" or "every",
    -0.06 if it is a preposition or conjunction such as "in" or "and";
  - -0.06 if the current token is whitespace-only or a digit.

Fitted on 8192 training rows, the held-out variance explained is about 0.6%. Token identity
alone (a 14k-entry table) reaches about 2%, and a small neural net on 16 tokens of context
about 2-3%: the rest of the component's activation is not carried by the words in the text.
"""

READS = ()

# Words after which the next word tends to be a time, place or condition phrase.
RELATIONAL = {
    "after", "before", "while", "between", "given", "when", "date", "upon", "behind",
    "inside", "near", "against",
}
DETERMINERS = {"the", "each", "every"}
PREPOSITIONS = {"in", "on", "at", "for", "and", "from"}


def step(carry, prefix, upstream):
    # carry: (document id of the last token, its position within the document)
    doc = prefix.document_ids[-1]
    if carry is None or doc != carry[0]:
        pos = 0
    else:
        pos = carry[1] + 1
    carry = (doc, pos)
    if pos == 0:
        return carry, 0.0  # the first token of a document: the component is silent
    value = -0.045
    if pos <= 3:
        value -= 0.09
    prev = prefix.token_strings[-2].strip().lower()
    cur = prefix.token_strings[-1].strip()
    if prev in RELATIONAL:
        value += 0.27
    elif prev in DETERMINERS:
        value += 0.15
    elif prev in PREPOSITIONS:
        value -= 0.06
    if cur == "" or cur.isdigit():
        value -= 0.06
    return carry, float(value)

"""Layer 15 MLP down-projection, component 976.

What it does: it fires on the word that comes between a clause's subject and its main
verb, the slot where a verb is about to come. Its output direction promotes verbs such
as know, want, understand and believe, so it tracks a finite verb being predicted after
an overt subject.

Strongest on:
  * subject pronouns that open a main clause ("... . I", "but we", "so they", "If you"),
  * the auxiliary, modal, negation or adverb right after such a subject
    ("I have", "we can", "they will", "he never", "we also", "I'm", "you've").
Weaker on object and possessive pronouns, "is/was/are", and "to". Slightly negative on
"and", "or", "for". Near zero on the, of, commas and most nouns.

The same word counts for less when the word before it is a content word, a wh-word
such as "that" or "what", or an article or preposition, and a subject pronoun before it
adds a bonus. It is zero at the start of a document.

The program scores each position from its own word (a table of word classes) and the
word before it (a role that scales the word's score). It keeps no state.
"""

READS = ()

SUBJECT_PRONOUNS = {"i", "we", "you", "he", "she", "they"}
MODALS = {"can", "will", "may", "might", "must", "should", "would", "could", "shall"}
HAVE_DO = {"have", "has", "had", "did", "do", "does", "need", "got", "want"}
NEGATION_ADVERBS = {"not", "never", "always", "also", "still", "just", "really", "already",
                    "probably", "only", "often", "even", "usually", "definitely", "certainly",
                    "actually"}
CONTRACTIONS = {"t", "ve", "ll", "m", "d", "re"}
OBJECT_OR_POSSESSIVE = {"me", "us", "him", "them", "who", "it", "his", "its", "their"}
BE_FORMS = {"is", "are", "was", "were", "be", "am"}
CONJUNCTIONS = {"and", "but", "so", "if", "though", "although", "yet", "because", "when",
                "while", "until", "then", "or"}
WH_WORDS = {"that", "what", "who", "where", "how", "why", "which", "whom", "whose", "when"}
ARTICLES_PREPOSITIONS = {"the", "a", "an", "of", "in", "to", "from", "with", "on", "at", "by",
                         "for"}
SENTENCE_ENDS = {".", "!", "?", ";", ":", ""}  # "" is a bare newline or whitespace token

# Word score: how strongly this word sits in the subject-to-verb slot.
WORD_SCORE = [
    (SUBJECT_PRONOUNS, 4.0),
    (NEGATION_ADVERBS, 3.0),
    (MODALS, 2.3),
    (HAVE_DO, 2.2),
    (CONTRACTIONS, 2.0),
    (OBJECT_OR_POSSESSIVE, 2.0),
    (BE_FORMS, 1.0),
    ({"s"}, 1.0),
    ({"to"}, 0.7),
    ({"and", "or", "for"}, -0.4),
]

# Role of the previous word: how much the word's score counts after it.
ROLE_SCALE = {"start": 0.0, "boundary": 1.1, "conjunction": 1.1, "subject": 2.2,
              "wh": 0.6, "article_preposition": 0.5, "other": 0.8}


def normal(text):
    return text.strip().lower().replace("’", "'").lstrip("'")


def word_score(word):
    for words, score in WORD_SCORE:
        if word in words:
            return score
    return 0.0


def previous_role(prefix):
    if len(prefix.token_ids) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return "start"
    word = normal(prefix.token_strings[-2])
    if word in SUBJECT_PRONOUNS or word == "it":
        return "subject"
    if word in CONJUNCTIONS:
        return "conjunction"
    if word in WH_WORDS:
        return "wh"
    if word in ARTICLES_PREPOSITIONS:
        return "article_preposition"
    if word in SENTENCE_ENDS:
        return "boundary"
    return "other"


def step(carry, prefix, upstream):
    word = normal(prefix.token_strings[-1])
    role = previous_role(prefix)
    value = word_score(word) * ROLE_SCALE[role]
    if role == "subject":
        value += 0.9
    return carry, float(value)

"""Layer 15, MLP hidden unit 984 (down_proj component 984).

Fires on binary plus and minus signs inside arithmetic, most of all the index
and offset arithmetic of code (`i - 1`, `n + 1`) and the algebra of maths. It is
strongest on a plus sign after a simple variable, stronger in code and where
the nearby text talks about indices, offsets or starting points, and weak
after a number. Everything else stays at zero, and the rule explains only a
little of the variance.
"""
import re

READS = ()

PLUS = {"+", " +"}
MINUS = {"-", " -", "−", " −"}
INDEX_LETTERS = set("ijknm")
INDEX_WORDS = re.compile(r"index|offset|start|begin|relative|idx", re.I)
CODE_MARKS = {"{", "}", ";", "(", ")", "[", "]", "=", "->", "$"}


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    tok = toks[-1]
    if tok not in PLUS and tok not in MINUS:
        return carry, 0.0
    if len(toks) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, 0.0
    before = toks[-2].strip()
    if re.fullmatch(r"\d+(\.\d+)?", before):
        value = 0.1
    elif before in INDEX_LETTERS:
        value = 1.5
    elif re.fullmatch(r"[A-Za-z_]\w*|[)\]]", before):
        value = 1.0
    else:
        value = 0.3
    window = toks[-30:]
    if INDEX_WORDS.search(" ".join(window)):
        value += 0.5
    if sum(1 for w in window if w.strip() in CODE_MARKS) >= 3:
        value += 0.5
    if tok in MINUS:
        value *= 0.5
    return carry, value

"""Clause-opening conjunctions, read as a negative response.

The component writes to the residual stream through layer 15's MLP. Its activation
is strongly negative on the word that opens a conditional, causal or concessive
clause ("if", "because", "since", "although", "despite", "unless", "though"), a bit
less negative on temporal or contrastive openers ("when", "while", "until", "after",
"but", "however", "where"), and slightly positive on words that state a consequence
("thus", "therefore", "hence", "so", "then"). Everywhere else it is near 0.

"if" meaning "whether" (after check, see, wonder, test, ...) is not a condition, and
the component stays near 0 there.

The program predicts from the current token and the one before it: no state is kept.
"""

READS = ()

# Activation on the opener, in the component's units (roughly its mean on that word).
CONDITIONAL_CAUSAL = {
    "if": -7.5, "because": -8.7, "since": -6.7, "although": -5.5, "though": -5.6,
    "despite": -7.9, "unless": -5.6, "whenever": -5.0, "elif": -6.3,
    "если": -9.1, "wenn": -8.9, "porque": -9.9, "如果": -7.8, "因为": -7.8,
    "由于": -9.5, "虽然": -7.3,
}
TEMPORAL_CONTRAST = {
    "when": -5.0, "while": -2.5, "until": -3.2, "once": -2.0, "after": -2.3,
    "however": -2.1, "where": -2.0, "but": -2.6, "given": -1.3, "as": -0.8,
}
CONSEQUENCE = {"thus": 0.8, "therefore": 0.8, "hence": 0.8, "so": 0.4, "then": 0.4}
# Verbs of checking or asking: "if" after one of these means "whether", not a condition.
WHETHER_CUES = {
    "check", "see", "sure", "know", "whether", "wonder", "test", "confirm", "ask",
    "verify", "wondered", "checking", "seeing", "asking", "out",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    same_doc = prefix.position > 0 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before = prefix.token_strings[-2].strip().lower() if same_doc else ""
    if word == "if" and before in WHETHER_CUES:
        return carry, 0.0
    for table in (CONDITIONAL_CAUSAL, TEMPORAL_CONTRAST, CONSEQUENCE):
        if word in table:
            return carry, float(table[word])
    return carry, 0.0

"""Layer 15's MLP hidden unit 994, as seen through one of its down_proj components.

The component reads almost only that hidden unit: its input direction is dominated by
unit 994 (about two thirds of its squared norm), so its activation tracks that unit's
value. The activation is mostly large, sparse spikes of both signs spread over many
words, with no simple rule covering most of them. The strongest and most readable spikes
are on compass directions in geographic text ("in south west London", "6 km south of
Jenin"), and on "of" after a direction or a part-of-place noun ("north of", "edge of").

So this program predicts:
- a compass word (north, south, east, west and compounds) -> a small positive value;
- an adjective compass form (northern, southern, eastern, western) -> a larger one;
- "of" right after a compass word -> a large positive value;
- "of" right after a part-of-place noun (edge, base, side, end, top, ...) -> a moderate value;
- everything else -> 0.

What it gets: on 1024 eval rows it explains about 0.6% of the variance (r = 0.09), and it
is roughly neutral in the model's output (the e2e KL is about the same as switching the
component off). What a lookup table of per-token means would add: about 3% of variance
out of sample; it would be a long list of arbitrary token ids, so it is not used here.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

# Compass words, as nouns and adverbs ("north", "south west") and as compounds.
COMPASS = {"north", "south", "east", "west", "northeast", "northwest", "southeast", "southwest"}
# Their adjective forms ("the northern part", "eastern Europe").
COMPASS_ADJ = {"northern", "southern", "eastern", "western"}
# Nouns that name a part or edge of a place or object ("the edge of", "base of").
PART = {
    "side", "edge", "end", "top", "bottom", "base", "surface", "portion", "region", "half",
    "front", "back", "middle", "inner", "outer", "rear", "part", "left", "right", "center",
    "corner", "version", "sides", "edges", "portions",
}

COMPASS_VALUE = 1.5
COMPASS_ADJ_VALUE = 5.0
OF_AFTER_COMPASS = 6.0
OF_AFTER_PART = 1.5


def _word(token: str) -> str:
    return token.strip().lower()


def step(carry, prefix, upstream: Mapping):
    word = _word(prefix.token_strings[-1])
    if word in COMPASS:
        return carry, COMPASS_VALUE
    if word in COMPASS_ADJ:
        return carry, COMPASS_ADJ_VALUE
    same_document = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    if word == "of" and same_document:
        before = _word(prefix.token_strings[-2])
        if before in COMPASS:
            return carry, OF_AFTER_COMPASS
        if before in PART:
            return carry, OF_AFTER_PART
    return carry, 0.0

"""Layer 15, MLP hidden unit 1003: a token-class bias, and little more.

Component p-82af68dd@100000/layers.15.mlp.down_proj:1003 reads the layer-15 MLP
hidden activations along one direction, which is mostly MLP hidden unit 1003
(about 44% of its squared norm). Its activation is small and noisy, mean about
-0.04, with rare large values (up to about +14 and -14) that depend on context
in ways no short rule captures. Token identity explains almost none of it.

What a short rule can capture is a class-level bias, measured on training text:
  - maths and code notation (=, ), (, arrows, approx, $, backticks) is pushed
    negative;
  - URL pieces (https, .com, ://) are negative;
  - Java class names after a package dot (".File", ".Log") are strongly negative;
  - completion words (" finished", " completed") are positive, the most of any class;
  - chat-template role tokens (assistant, user, <|im_start|>) are slightly positive.
Every other token gets the baseline -0.036. The program keeps no state: it reads
only the newest token.
"""

import re

MATH_EQ = {"=", " =", ")=", "=-", " ==", ":="}
MATH_SYMBOL = {" (", "(", " →", "→", "≈", " $", "$", " `", "`", " |"}
URL = {" https", "https", " http", "http", ".com", "://", "/"}
DONE = {" finished", " completed", " following"}
CHAT = {"assistant", "user", "<|im_start|>", "</think>", "<tool_response>", "<tool_call>"}
JAVA_CLASS = re.compile(r"^\.[A-Z]")

BASELINE = -0.036
CLASS_MEAN = {
    "math_eq": -0.20,
    "math_symbol": -0.16,
    "url": -0.10,
    "java_class": -0.35,
    "done": 0.60,
    "chat": 0.10,
}

READS = ()


def token_class(tok: str) -> str | None:
    if tok in MATH_EQ:
        return "math_eq"
    if tok in MATH_SYMBOL:
        return "math_symbol"
    if tok in URL:
        return "url"
    if JAVA_CLASS.match(tok):
        return "java_class"
    if tok in DONE:
        return "done"
    if tok in CHAT:
        return "chat"
    return None


def step(carry, prefix, upstream):
    cls = token_class(prefix.token_strings[-1])
    return carry, CLASS_MEAN[cls] if cls else BASELINE

"""Predict layers.15 MLP unit-1007's down-projection component from the kind of the current token.

What this component is: a rank-one readout of layer 15's MLP hidden state (the vector that
down_proj reads). Its activation is a diffuse, heavy-tailed signal, spread over thousands of
hidden units (unit 1007 alone is about 11% of its variance). It is almost never off, but
it carries no simple surface structure, and it barely affects the model's output.

What this program does: it looks only at the newest token and gives a level by its kind:
- line breaks (\n, \r\n) sit lowest, about -0.13 on average;
- CJK (Han) characters about -0.10;
- punctuation about -0.065;
- other tokens about -0.04; spaces about 0.
These are means over about 2,000 training rows. They are real but small: this explains
essentially none of the variance (about 0 on eval). A per-token table would add about 1-2%
held-out on a sample, and it would be unreadable.
"""

import regex

READS = ()
LEVELS = {"newline": -0.13, "han": -0.10, "punct": -0.065, "space": -0.005, "other": -0.04}


def kind(text):
    if "\n" in text or "\r" in text:
        return "newline"
    if not text.strip():
        return "space"
    if regex.search(r"\p{Script=Han}", text):
        return "han"
    if regex.fullmatch(r"\s?[\p{P}\p{S}]+", text):
        return "punct"
    return "other"


def step(carry, prefix, upstream):
    return carry, LEVELS[kind(prefix.token_strings[-1])]

"""Layer 15 MLP down-projection, component 1009: a weak signal that is mostly unexplained.

The component reads the MLP hidden state and writes a small vector into the residual
stream. Its activation has mean about -0.01 and std about 0.3, and it hardly depends on
the current token: a lookup of the token's identity explains about 2-3% of its variance,
and the previous token, the document, or the model's own uncertainty explain less. Its
largest single input is MLP neuron 1009, which is high on sequencing and time words
("later", "became", "currently", "now", "again", "until") and low on code and
punctuation; across all its inputs that signal is weak.

So this program makes a coarse guess from the token's surface form alone, using the mean
activation of each class on training text:
  * an ordinary English word with a leading space (" the", " later"): about +0.01;
  * a token containing a digit, or punctuation / code symbols: about -0.03 to -0.04;
  * whitespace-only tokens: about -0.03;
  * everything else (words without a leading space, CJK, partial bytes): -0.02.
Position 0 of a row is a constant 0.005.
"""
import re
from collections.abc import Mapping

READS: tuple[str, ...] = ()

SPACED_WORD = re.compile(r" [A-Za-z]+")
DIGIT = re.compile(r".*\d.*", re.S)
PUNCT_CODE = re.compile(r"\s*[^\w\s]+\s*|.*[{}();=<>\[\]_].*", re.S)
SPACE = re.compile(r"\s+")


def value_of(token: str) -> float:
    if "�" in token:
        return -0.02
    if SPACED_WORD.fullmatch(token):
        return 0.010
    if DIGIT.fullmatch(token):
        return -0.039
    if PUNCT_CODE.fullmatch(token):
        return -0.034
    if SPACE.fullmatch(token):
        return -0.031
    return -0.02


def step(carry, prefix, upstream: Mapping):
    if prefix.position == 0:
        return carry, 0.005
    return carry, value_of(prefix.token_strings[-1])

"""Layer 15, MLP hidden unit 1011 (the down_proj component, almost all of its input weight).

What it does, in plain terms: this unit is a weak, noisy detector for the words that link a
claim to its consequence or contrast ("but", "then", "so", "therefore", "means", "就是"), and
for the comma that ends an "if ... ," or "when ... ," clause, which is where a consequence is
about to follow. It is pushed negative by comparison and conversion relations: "vs", "<=",
"between X and Y", "from X to Y". Most of its variance is not explained by any word or clause,
so this program captures only the largest, most readable part of it.

The program is a small rule set over the text so far. Each rule gives a fixed value, roughly
the average activation in that context. Token identity alone explains under 4% of the variance,
so these rules explain about 1 to 1.5%.
"""
READS = ()

# Words that tie a claim to its consequence or contrast.
CONSEQUENCE = {"but", "however", "therefore", "thus", "hence", "then", "so", "implies", "means",
               "iff", "equivalent", "corresponds", "但", "但是", "就是", "所以", "那么",
               "но", "pero", "mas", "mais"}
# Clause-introducing words and the equals sign, weakly positive.
WEAK_POSITIVE = {"when", "as", "while", "what"}
# Comparison operators: negative.
COMPARE = {"vs", "versus", "<=", ">=", "≤", "≥", "divides"}
# Words that set up a relation or conversion ("from X to Y", "convert X to Y", "between X and Y").
RELATION_FRAME = {"convert", "converting", "conversion", "converter", "relationship", "relation",
                  "difference", "between", "from", "ratio", "compare", "comparison"}
# Sentence openers whose first comma marks the end of a condition.
CONDITION_OPENERS = {"if", "when", "as", "once", "whenever", "suppose", "given"}
SENTENCE_END = {".", "!", "?"}


def step(carry, prefix, upstream):
    """Value for the newest token, given the sentence state carried from earlier tokens."""
    if carry is None or carry["doc"] != prefix.document_ids[-1]:
        carry = {"doc": prefix.document_ids[-1], "first": "", "commas": 0, "words": []}
    s = prefix.token_strings[-1]
    w = s.strip()
    lw = w.lower()
    if "\n" in s or w in SENTENCE_END:
        carry["first"], carry["commas"], carry["words"] = "", 0, []
        return carry, 0.0
    if w and not carry["first"]:
        carry["first"] = lw
    recent = carry["words"][-8:]
    carry["words"] = carry["words"][-7:] + [lw]
    if w == ",":
        value = 0.5 if carry["first"] in CONDITION_OPENERS and carry["commas"] == 0 else 0.0
        carry["commas"] += 1
        return carry, value
    if lw in CONSEQUENCE:
        return carry, 0.7
    if w == "=":
        return carry, 0.25
    if lw in WEAK_POSITIVE:
        return carry, 0.3
    if w in COMPARE:
        return carry, -0.8
    if lw == "and" and "between" in recent:
        return carry, -1.6
    if lw == "to" and any(x in RELATION_FRAME for x in recent):
        return carry, -0.9
    return carry, 0.0

"""Discourse-connective polarity: the component is pushed negative by contrast words
("but", "however", "但", "но", "pero") and positive by consequence words ("therefore",
"thus", "so", "因此", "поэтому"). Everything else predicts 0, its near-zero average.

Reads only the newest token. The prediction is that token's activation: a clear
adversative connective -0.9, a weaker one ("wait", "yet", "though", "since") -0.35,
a consequence connective +0.35.
"""

READS = ()

CONTRAST = {"but", "however", "但", "但是", "然而", "可是", "不过", "pero", "aber", "mais",
            "ale", "но", "однако", "nhưng", "doch", "しかし", "だが"}
WEAK_CONTRAST = {"wait", "yet", "though", "although", "since"}
CONSEQUENCE = {"therefore", "thus", "hence", "so", "also", "因此", "所以", "поэтому", "quindi", "donc"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in CONTRAST:
        return None, -0.9
    if word in WEAK_CONTRAST:
        return None, -0.35
    if word in CONSEQUENCE:
        return None, 0.35
    return None, 0.0
